from pathlib import Path
import base64,json
ROOT=Path(__file__).resolve().parent.parent;OUT=Path('/workspace/artifacts/Focus-glass-demo-20261029.html')
styles='\n'.join((ROOT/'web'/name).read_text() for name in ['focus.css','focus-app.css','focus-experience.css','focus-skin.css','focus-art-skins.css','focus-glass.css'])
for skin in ['chrome','garnet']:
    data='data:image/webp;base64,'+base64.b64encode((ROOT/f'web/skins/{skin}.webp').read_bytes()).decode();styles=styles.replace('/skins/'+skin+'.webp',data)
logo='data:image/svg+xml;base64,'+base64.b64encode((ROOT/'web/icons/focus.svg').read_bytes()).decode()
motion=(ROOT/'web/focus-skins.mjs').read_text().replace('export const ','const ')+ '\n'+(ROOT/'web/focus-glass.mjs').read_text().replace("import {glassSkin} from './focus-skins.mjs';",'').replace('export class GlassMotion','class GlassMotion')
tasks=''.join('<div class="row task-row"><div class="task-select"><span class="body"><strong>'+name+' <span class="work-title">'+work+'</span></strong><small>'+time+'</small></span></div></div>' for name,work,time in [('学習','演習','09:00–09:25'),('制作','作業','10:00–10:25'),('英語','復習','11:00–11:25'),('読書','読書','12:00–12:25'),('運動','運動','13:00–13:25')])
timeline=''.join('<div class="demo-hour"><small>'+str(i).zfill(2)+':00</small><div class="demo-slot">'+(['学習','制作','英語','読書','運動'][i-9] if i<14 else '')+'</div></div>' for i in range(9,19))
markup='''<!doctype html><html lang="ja" data-skin="chrome" data-theme="dark"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focus — スクロールとガラスの反射</title><link rel="icon" href="LOGO"><style>STYLES
.demo-tools{position:sticky;top:0;z-index:50;display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-left:196px;padding:12px 32px;background:color-mix(in srgb,var(--bg) 95%,transparent);border-bottom:1px solid var(--line)}.demo-tools button{font-size:12px;padding:7px 12px;min-height:36px}.demo-tools label{font-size:12px;display:flex;align-items:center;gap:6px}.demo-tools input{width:auto}.demo-tools small{font-size:11px;color:var(--muted)}.demo-hour{display:flex;gap:16px;align-items:center;min-height:60px;border-top:1px solid var(--line)}.demo-hour>small{width:45px;color:var(--muted);font-size:11px}.demo-slot{height:32px;flex:1;border-left:2px solid var(--green);background:color-mix(in srgb,var(--control) 70%,transparent);padding:6px 10px;font-size:12px}.demo-tools button:focus-visible{outline:2px solid var(--green)}.demo-foot{color:var(--muted);font-size:11px;margin-top:15px;padding-bottom:20px}#primary-nav a{pointer-events:none}.demo-tools [aria-pressed=true]{background:var(--green);color:var(--primary-ink);border-color:transparent}.demo-tools label{white-space:nowrap}@media(max-width:1000px) and (min-width:761px){.demo-tools{margin-left:160px;padding:12px 20px}}@media(max-width:760px){.demo-tools{margin:0;padding:10px 12px;gap:7px}.demo-tools small{width:100%}.demo-tools button{font-size:11px;padding:7px 10px}.demo-tools label{font-size:11px}.demo-tools>strong{display:none}.demo-foot{margin-bottom:65px}}
</style><body><aside id="sidebar"><a class="brand"><img src="LOGO" alt="">Focus</a><nav id="primary-nav"><a aria-current="page">ホーム</a><a>タスク</a><a>記録</a></nav></aside><div class="demo-tools"><strong>Focus</strong><button data-skin="glass">Glass</button><button data-skin="chrome" aria-pressed="true">Chrome</button><button data-skin="garnet">Garnet</button><button id="theme">ライト</button><label><input id="reflection" type="checkbox" checked>反射</label><small>スクロールで確認 · 架空データのプレビュー</small></div><main class="app-workspace"><div class="page-title"><h1>ガラスの反射</h1></div><div class="dashboard-grid"><section class="panel session-panel" data-card="capture"><div class="session-heading"><div class="session-selection"><span>学習</span><small>演習</small></div></div><div class="clock-row"><div class="timer-output">00:00:00</div><button class="primary-button" aria-disabled="true">開始</button></div><div class="mode-switch"><button aria-pressed="true">ストップウォッチ</button><button>ポモドーロ</button><button>タイマー</button></div></section><section class="panel today-panel" data-card="plan"><div class="date-heading"><h2>今日のタスク</h2></div>TASKS</section><section class="panel day-panel" data-card="progress"><div class="date-heading"><h2>日程</h2></div>TIMELINE</section><section class="panel" data-card="logs"><h2>直近の記録</h2><div class="row"><span class="body">学習 · 演習</span><small>25分</small></div><div class="row"><span class="body">制作 · 作業</span><small>45分</small></div><div class="row"><span class="body">読書</span><small>30分</small></div></section></div><p class="demo-foot">反射の比較用です。タスク・計測ボタンは記録を作りません。Chrome/Edgeは背景の屈折も使用。Safariはぼかしと反射の表示へ切り替えます。端末の視差効果軽減設定では反射を静止します。Apple純正のLiquid Glassを使ったものではありません。</p></main><script>MOTION
const optics=new GlassMotion();let skin='chrome';function apply(){document.documentElement.dataset.skin=skin;optics.configure({skin,enabled:document.querySelector('#reflection').checked});for(const button of document.querySelectorAll('.demo-tools [data-skin]'))button.setAttribute('aria-pressed',button.dataset.skin===skin);}for(const button of document.querySelectorAll('.demo-tools [data-skin]'))button.onclick=()=>{skin=button.dataset.skin;apply();};document.querySelector('#reflection').onchange=apply;document.querySelector('#theme').onclick=()=>{const light=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=light?'light':'dark';document.querySelector('#theme').textContent=light?'ダーク':'ライト';};apply();
</script></html>'''
markup=markup.replace('LOGO',logo).replace('STYLES',styles).replace('TASKS',tasks).replace('TIMELINE',timeline).replace('MOTION',motion)
OUT.write_text(markup);print(json.dumps({'file':str(OUT),'bytes':OUT.stat().st_size}))
